// STARTUPE2 as a design reaching the configuration flash's clock uses it. Generated by tools/vivado-parity/gen_config.py.
module startup_flash (
    input  wire clk,
    input  wire si,
    output reg  so
);
  reg [7:0] sr;
  always @(posedge clk) sr <= {sr[6:0], si};
  wire o_eos;
  STARTUPE2 dut (.CLK(1'b0), .GSR(1'b0), .GTS(1'b0), .KEYCLEARB(1'b1), .PACK(1'b0), .USRCCLKO(sr[1]), .USRCCLKTS(1'b0), .USRDONEO(1'b1), .USRDONETS(1'b1), .EOS(o_eos));
  reg q;
  always @(posedge clk) q <= (^o_eos);
  always @(posedge clk) so <= q ^ sr[0];
endmodule
